document.addEventListener("DOMContentLoaded", () => {
  bootstrap().catch((error) => {
    console.error(error);
    state.booting = false;
    setFlash("No se pudo iniciar la aplicacion.", "error");
    render();
  });
});

async function bootstrap() {
  if (state.token) {
    try {
      await hydrateAuthenticatedState();
    } catch (error) {
      console.error(error);
      clearSession();
      setFlash(
        "La sesion anterior ya no es valida. Inicia sesion nuevamente.",
        "error",
      );
    }
  }

  if (!state.formDraft) {
    state.formDraft = createEmptyDraft();
  }

  state.booting = false;
  render();
}

function createEmptyDesktopPrintingState() {
  return {
    loading: false,
    loaded: false,
    error: "",
    items: [],
  };
}

function getRockyClientBridge() {
  if (
    typeof window === "undefined" ||
    !window.rockyClient ||
    typeof window.rockyClient !== "object"
  ) {
    return null;
  }

  return window.rockyClient;
}

function desktopClientSupportsPrinting() {
  const bridge = getRockyClientBridge();
  return Boolean(
    bridge &&
    typeof bridge.listPrinters === "function" &&
    typeof bridge.printHtml === "function",
  );
}

function getDetectedDesktopPrinters() {
  return Array.isArray(state.desktopPrinting?.items)
    ? state.desktopPrinting.items
    : [];
}

function normalizeDesktopPrinterLookupValue(value) {
  return String(value || "")
    .trim()
    .toLowerCase();
}

function buildDesktopPrinterLookupText(printer = {}) {
  return [printer?.name, printer?.displayName, printer?.description]
    .map((value) => normalizeDesktopPrinterLookupValue(value))
    .filter(Boolean)
    .join(" ");
}

function isVirtualDesktopPrinter(printer = {}) {
  const haystack = buildDesktopPrinterLookupText(printer);
  if (!haystack) {
    return false;
  }

  return [
    "microsoft print to pdf",
    "print to pdf",
    "pdf",
    "microsoft xps",
    "xps",
    "fax",
    "onenote",
    "adobe pdf",
    "virtual",
    "anydesk printer",
  ].some((pattern) => haystack.includes(pattern));
}

function scorePreferredDesktopPrinter(printer = {}) {
  const haystack = buildDesktopPrinterLookupText(printer);
  let score = 0;

  if (printer?.isAvailable !== false) {
    score += 50;
  }
  if (!isVirtualDesktopPrinter(printer)) {
    score += 200;
  }
  if (printer?.isDefault) {
    score += 20;
  }

  [
    ["dp8", 240],
    ["bixolon", 220],
    ["thermal", 180],
    ["termica", 180],
    ["receipt", 150],
    ["ticket", 150],
    ["pos", 120],
    ["epson tm", 110],
    ["generic / text only", 90],
  ].forEach(([pattern, value]) => {
    if (haystack.includes(pattern)) {
      score += value;
    }
  });

  return score;
}

function getDefaultDesktopPrinterName() {
  const printers = getDetectedDesktopPrinters();
  const physicalPrinters = printers.filter(
    (item) => !isVirtualDesktopPrinter(item),
  );
  const candidates = physicalPrinters.length ? physicalPrinters : printers;
  const printer =
    [...candidates].sort(
      (left, right) =>
        scorePreferredDesktopPrinter(right) -
        scorePreferredDesktopPrinter(left),
    )[0] || null;
  return String(printer?.name || "").trim();
}

async function loadDesktopPrinters(options = {}) {
  const { renderAfter = true, silent = false } = options;
  const bridge = getRockyClientBridge();
  if (!bridge || typeof bridge.listPrinters !== "function") {
    state.desktopPrinting = {
      ...createEmptyDesktopPrintingState(),
      loaded: true,
    };
    if (renderAfter) {
      render();
    }
    return [];
  }

  state.desktopPrinting = {
    ...state.desktopPrinting,
    loading: true,
    error: "",
  };
  if (renderAfter) {
    render();
  }

  try {
    const result = await bridge.listPrinters();
    const printers = Array.isArray(result?.printers)
      ? result.printers.filter((item) => String(item?.name || "").trim())
      : [];

    state.desktopPrinting = {
      loading: false,
      loaded: true,
      error: "",
      items: printers,
    };

    return printers;
  } catch (error) {
    state.desktopPrinting = {
      loading: false,
      loaded: false,
      error: extractErrorMessage(error),
      items: [],
    };

    if (!silent) {
      setFlash(
        `No se pudieron detectar las impresoras de esta PC: ${extractErrorMessage(error)}`,
        "error",
      );
    }

    return [];
  } finally {
    if (renderAfter) {
      render();
    }
  }
}
