function render() {
  const app = document.getElementById("app");
  if (!app) {
    return;
  }

  if (state.booting) {
    clearExistenceAutoRefresh();
    app.innerHTML = renderBootScreen();
    return;
  }

  if (!state.token || !state.user) {
    clearExistenceAutoRefresh();
    app.innerHTML = renderLoginView();
    bindLoginEvents();
    bindFlashEvents();
    return;
  }

  app.innerHTML = renderShellView();
  bindShellEvents();
  bindFlashEvents();
  syncExistenceAutoRefresh();
}

