function renderCashRegistersTable() {
  const items = Array.isArray(state.cashRegisters.items)
    ? state.cashRegisters.items
    : [];
  const search = normalizeSearchText(state.cashRegisters.search);
  const visibleItems = search
    ? items.filter((item) =>
        normalizeSearchText(
          `${item.serie || ""} ${item.numeroCaja || ""} ${item.facturaInicial || ""} ${item.ultimaFactura || ""} ${item.statusNombre || ""}`,
        ).includes(search),
      )
    : items;

  if (!visibleItems.length) {
    return `
      <div class="empty-state">
        <h3>Sin aperturas</h3>
        <p>${search ? "No hay resultados para la busqueda actual." : "No hay aperturas de caja registradas todavia."}</p>
      </div>
    `;
  }

  return `
    <div class="table-wrap cash-register-table-wrap">
      <table class="data-table">
        <thead>
          <tr>
            <th>Serie</th>
            <th>Fecha</th>
            <th>Caja</th>
            <th>Factura inicial</th>
            <th>Ultima factura</th>
            <th>Status</th>
            <th>Accion</th>
          </tr>
        </thead>
        <tbody>
          ${visibleItems
            .map((item) => {
              const key = buildCashRegisterKey(item.serie, item.fecha);
              const isSelected =
                String(state.cashRegisters.selectedKey || "") === key;

              return `
                <tr class="${isSelected ? "is-selected-row" : ""}">
                  <td><strong>${escapeHtml(item.serie || "-")}</strong></td>
                  <td>${escapeHtml(formatDateOnlyDisplay(item.fecha))}</td>
                  <td>${escapeHtml(toDisplayValue(item.numeroCaja))}</td>
                  <td>${escapeHtml(toDisplayValue(item.facturaInicial))}</td>
                  <td>${escapeHtml(toDisplayValue(item.ultimaFactura))}</td>
                  <td>${renderCashRegisterStatusBadge(item.status)}</td>
                  <td class="sucursal-row-actions">
                    <button
                      class="button button-ghost"
                      type="button"
                      data-caja-select="${escapeHtml(item.serie || "")}"
                      data-caja-fecha="${escapeHtml(toDateInputValue(item.fecha))}"
                    >
                      Abrir
                    </button>
                    <button
                      class="button button-danger"
                      type="button"
                      data-delete-caja="${escapeHtml(item.serie || "")}"
                      data-delete-caja-fecha="${escapeHtml(toDateInputValue(item.fecha))}"
                      ${state.cashRegisters.deleting || Number(item.status || 0) !== 0 ? "disabled" : ""}
                    >
                      Eliminar
                    </button>
                  </td>
                </tr>
              `;
            })
            .join("")}
        </tbody>
      </table>
    </div>
  `;
}

function renderCashRegisterStatusBadge(status) {
  const numericStatus = Number(status ?? 0);
  let label = "Apertura hecha";
  if (numericStatus === 1) {
    label = "Apertura con ventas";
  } else if (numericStatus === 2) {
    label = "Caja cerrada";
  }

  return `<span class="modern-chip">${escapeHtml(label)}</span>`;
}

function renderCashRegisterConditionText(status) {
  const numericStatus = Number(status ?? 0);
  if (numericStatus === 2) {
    return "Cerrada";
  }

  if (numericStatus === 1) {
    return "Abierta con ventas";
  }

  return "Abierta";
}

function getCloseableCashRegisters() {
  const items = Array.isArray(state.cashRegisters.items)
    ? state.cashRegisters.items
    : [];
  return items.filter((item) => Number(item?.status ?? 0) !== 2);
}

function getCurrentTimeInputValue() {
  const now = new Date();
  const hours = String(now.getHours()).padStart(2, "0");
  const minutes = String(now.getMinutes()).padStart(2, "0");
  return `${hours}:${minutes}`;
}

function buildCashRegisterCloseDraft(item, previousDraft = null) {
  const nextDraft = cashRegisterToDraft(item);
  const itemKey = buildCashRegisterKey(item?.serie, item?.fecha);
  const previousKey = buildCashRegisterKey(
    previousDraft?.originalSerie || previousDraft?.serie,
    previousDraft?.originalFecha || previousDraft?.fecha,
  );
  const preservedCloseHour =
    itemKey === previousKey
      ? String(previousDraft?.horaCierre || "").trim()
      : "";

  return {
    ...nextDraft,
    horaCierre: toInputValue(
      preservedCloseHour || nextDraft.horaCierre || getCurrentTimeInputValue(),
    ),
  };
}

