async function loadImpuestos(options = {}) {
  const { renderAfter = true } = options;
  state.impuestos.loading = true;
  if (renderAfter) {
    render();
  }

  try {
    const response = await apiFetch("/inventory/catalogs/impuestos");
    state.impuestos.items = Array.isArray(response.items) ? response.items : [];

    if (!state.impuestos.draft?.codigo) {
      state.impuestos.draft = createEmptyImpuestoDraft(state.impuestos.items);
    }
  } catch (error) {
    console.error(error);
    setFlash(`No se pudieron cargar los impuestos: ${extractErrorMessage(error)}`, "error");
  } finally {
    state.impuestos.loading = false;
    if (renderAfter) {
      render();
    }
  }
}

async function saveImpuesto() {
  const draft = state.impuestos.draft || createEmptyImpuestoDraft(state.impuestos.items);
  const validationMessage = validateImpuestoDraft(draft);
  if (validationMessage) {
    setFlash(validationMessage, "error");
    render();
    return;
  }

  state.impuestos.saving = true;
  clearFlash();
  render();

  try {
    const response = await apiFetch("/inventory/catalogs/impuestos", {
      method: "POST",
      body: buildImpuestoPayload(draft),
    });

    state.impuestos.selectedCodigo = response.item?.codigo || draft.codigo;
    state.impuestos.draft = impuestoToDraft(response.item);
    await loadImpuestos({ renderAfter: false });
    if (userCanAccessFullInventory()) {
      await loadCreationMetadata({ renderAfter: false });
    }
    setFlash(`Impuesto ${response.item?.codigo || draft.codigo} guardado correctamente.`, "success");
  } catch (error) {
    console.error(error);
    setFlash(extractErrorMessage(error), "error");
  } finally {
    state.impuestos.saving = false;
    render();
  }
}

async function loadBancos(options = {}) {
  const { renderAfter = true } = options;
  state.bancos.loading = true;
  state.bancos.loadingMetadata = true;
  if (renderAfter) {
    render();
  }

  try {
    const params = new URLSearchParams();
    const searchValue = String(state.bancos.search || "").trim();
    if (searchValue) {
      params.set("buscar", searchValue);
    }
    params.set("limit", "100");

    const [metadataResponse, listResponse] = await Promise.all([
      apiFetch("/bancos/metadata"),
      apiFetch(`/bancos?${params.toString()}`),
    ]);

    state.bancos.metadata = metadataResponse || {
      defaults: {},
    };
    state.bancos.items = Array.isArray(listResponse?.bancos)
      ? listResponse.bancos
      : [];

    if (state.bancos.selectedCodigo) {
      const selected = state.bancos.items.find(
        (item) =>
          String(item?.codigo || "").trim() ===
          String(state.bancos.selectedCodigo || "").trim(),
      );
      if (selected) {
        state.bancos.draft = bancoToDraft(selected, state.bancos.metadata);
      }
    } else if (!state.bancos.draft?.originalCodigo) {
      state.bancos.draft = createEmptyBancoDraft(state.bancos.metadata);
    }
  } catch (error) {
    console.error(error);
    state.bancos.items = [];
    state.bancos.metadata = state.bancos.metadata || {
      defaults: {},
    };
    setFlash(
      `No se pudo cargar el catalogo de bancos: ${extractErrorMessage(error)}`,
      "error",
    );
  } finally {
    state.bancos.loading = false;
    state.bancos.loadingMetadata = false;
    if (renderAfter) {
      render();
    }
  }
}

async function loadBancoForEdit(codigo) {
  const normalizedCodigo = String(codigo || "").trim();
  if (!normalizedCodigo) {
    return;
  }

  state.bancos.loading = true;
  clearFlash();
  render();

  try {
    if (!state.bancos.metadata) {
      state.bancos.metadata = await apiFetch("/bancos/metadata");
    }

    const response = await apiFetch(
      `/bancos/${encodeURIComponent(normalizedCodigo)}`,
    );
    const banco = response?.banco || null;
    if (!banco) {
      throw new Error("Banco no encontrado.");
    }

    state.bancos.selectedCodigo = String(banco.codigo || normalizedCodigo);
    state.bancos.draft = bancoToDraft(banco, state.bancos.metadata);
  } catch (error) {
    console.error(error);
    setFlash(extractErrorMessage(error), "error");
  } finally {
    state.bancos.loading = false;
    render();
  }
}

async function saveBanco() {
  const draft =
    state.bancos.draft || createEmptyBancoDraft(state.bancos.metadata);
  const validationMessage = validateBancoDraft(draft);
  if (validationMessage) {
    setFlash(validationMessage, "error");
    render();
    return;
  }

  state.bancos.saving = true;
  clearFlash();
  render();

  try {
    const payload = buildBancoPayload(draft);
    const response = draft.originalCodigo
      ? await apiFetch(`/bancos/${encodeURIComponent(draft.originalCodigo)}`, {
          method: "PATCH",
          body: payload,
        })
      : await apiFetch("/bancos", {
          method: "POST",
          body: payload,
        });

    const banco = response?.banco || null;
    state.bancos.selectedCodigo = String(
      banco?.codigo || payload.codigo || "",
    );
    state.bancos.draft = bancoToDraft(banco, state.bancos.metadata);
    await loadBancos({ renderAfter: false });
    setFlash(
      draft.originalCodigo
        ? `Banco ${banco?.codigo || draft.originalCodigo} actualizado correctamente.`
        : `Banco ${banco?.codigo || payload.codigo || ""} guardado correctamente.`,
      "success",
    );
  } catch (error) {
    console.error(error);
    setFlash(extractErrorMessage(error), "error");
  } finally {
    state.bancos.saving = false;
    render();
  }
}

async function deleteBanco(codigo) {
  const normalizedCodigo = String(codigo || "").trim();
  if (!normalizedCodigo) {
    return;
  }

  const confirmed = window.confirm(
    `Se eliminara el banco ${normalizedCodigo}. Deseas continuar?`,
  );
  if (!confirmed) {
    return;
  }

  state.bancos.deleting = true;
  clearFlash();
  render();

  try {
    await apiFetch(`/bancos/${encodeURIComponent(normalizedCodigo)}`, {
      method: "DELETE",
    });

    resetBancoDraft();
    await loadBancos({ renderAfter: false });
    setFlash(`Banco ${normalizedCodigo} eliminado correctamente.`, "success");
  } catch (error) {
    console.error(error);
    setFlash(extractErrorMessage(error), "error");
  } finally {
    state.bancos.deleting = false;
    render();
  }
}

