function createEmptyFacturacionLineDraft() {
  return {
    priceList: "detal",
    codigoBarra: "",
    nombre: "",
    precio: "",
    cantidad: "",
    subtotal: "",
    descuentoPorcentaje: "",
    descuentoMonto: "",
    precioDetal: "",
    precioMayor: "",
    precioAfiliado: "",
    precioPromocion: "",
    promocionActiva: false,
  };
}

function normalizeFacturacionLineDraft(line = {}) {
  const base = createEmptyFacturacionLineDraft();
  return {
    ...base,
    ...(line || {}),
    priceList: normalizeFacturacionPriceList(line?.priceList),
    codigoBarra: toInputValue(line?.codigoBarra),
    nombre: toInputValue(line?.nombre),
    precio: toInputValue(line?.precio),
    cantidad: toInputValue(line?.cantidad),
    subtotal: toInputValue(line?.subtotal),
    descuentoPorcentaje: toInputValue(line?.descuentoPorcentaje),
    descuentoMonto: toInputValue(line?.descuentoMonto),
    precioDetal: toInputValue(line?.precioDetal),
    precioMayor: toInputValue(line?.precioMayor),
    precioAfiliado: toInputValue(line?.precioAfiliado),
    precioPromocion: toInputValue(line?.precioPromocion),
    promocionActiva: Boolean(line?.promocionActiva),
  };
}

function normalizeFacturacionItems(items) {
  const normalized = Array.isArray(items)
    ? items.slice(0, 11).map((item) => normalizeFacturacionLineDraft(item))
    : [];
  while (normalized.length < 11) {
    normalized.push(createEmptyFacturacionLineDraft());
  }
  return normalized;
}

function normalizeFacturacionDraft(draft = {}) {
  const base = createEmptyFacturacionDraft();
  return {
    ...base,
    ...(draft || {}),
    frozenId: String(draft?.frozenId || "").trim(),
    priceList: normalizeFacturacionPriceList(draft?.priceList),
    overrideDiscountAuthorized: Boolean(draft?.overrideDiscountAuthorized),
    overrideDiscountActive: Boolean(draft?.overrideDiscountActive),
    overrideDiscountPercent: toInputValue(draft?.overrideDiscountPercent),
    clienteCodigo: toInputValue(draft?.clienteCodigo),
    clienteNombre: toInputValue(draft?.clienteNombre),
    clienteInfo: toInputValue(draft?.clienteInfo),

    clienteTelefono: toInputValue(draft?.clienteTelefono),

    clienteDireccion: toInputValue(draft?.clienteDireccion),

    vendedorCedula: toInputValue(draft?.vendedorCedula),
    vendedorNombre: toInputValue(draft?.vendedorNombre),
    vendedorInfo: toInputValue(draft?.vendedorInfo),
    emisionContingencia: Boolean(draft?.emisionContingencia),
    items: normalizeFacturacionItems(draft?.items),
  };
}

function captureFacturacionDraft() {
  state.facturacion.draft = readFacturacionDraft();
}

function readFacturacionDraft() {
  const currentDraft = normalizeFacturacionDraft(
    state.facturacion.draft || createEmptyFacturacionDraft(),
  );
  const clienteCodigo = document.querySelector(
    "[data-facturacion-cliente-codigo]",
  );
  const clienteNombre = document.querySelector(
    "[data-facturacion-cliente-nombre]",
  );
  const clienteInfo = document.querySelector("[data-facturacion-cliente-info]");
  const vendedorCedula = document.querySelector(
    "[data-facturacion-vendedor-cedula]",
  );
  const vendedorNombre = document.querySelector(
    "[data-facturacion-vendedor-nombre]",
  );
  const vendedorInfo = document.querySelector(
    "[data-facturacion-vendedor-info]",
  );
  const contingencia = document.querySelector(
    "[data-facturacion-contingencia]",
  );
  const lineCodeInputs = Array.from(
    document.querySelectorAll("[data-facturacion-line-codigo]"),
  );
  const lineQuantityInputs = Array.from(
    document.querySelectorAll("[data-facturacion-line-cantidad]"),
  );
  const currentItems =
    Array.isArray(currentDraft.items) && currentDraft.items.length
      ? currentDraft.items
      : createEmptyFacturacionItems();
  const items = currentItems.map((item, index) => {
    const codeInput = lineCodeInputs[index];
    const quantityInput = lineQuantityInputs[index];
    return recalculateFacturacionLineAmounts({
      ...item,
      codigoBarra:
        codeInput instanceof HTMLInputElement
          ? codeInput.value
          : item.codigoBarra,
      cantidad:
        quantityInput instanceof HTMLInputElement
          ? quantityInput.value
          : item.cantidad,
    });
  });

  return {
    frozenId: currentDraft.frozenId,
    priceList: currentDraft.priceList,
    overrideDiscountAuthorized: currentDraft.overrideDiscountAuthorized,
    overrideDiscountActive: currentDraft.overrideDiscountActive,
    overrideDiscountPercent: currentDraft.overrideDiscountPercent,
    clienteCodigo:
      clienteCodigo instanceof HTMLInputElement
        ? clienteCodigo.value
        : currentDraft.clienteCodigo,
    clienteNombre:
      clienteNombre instanceof HTMLInputElement
        ? clienteNombre.value
        : currentDraft.clienteNombre,
    clienteInfo:
      clienteInfo instanceof HTMLInputElement
        ? clienteInfo.value
        : currentDraft.clienteInfo,
    clienteTelefono: currentDraft.clienteTelefono,
    clienteDireccion: currentDraft.clienteDireccion,

    vendedorCedula:
      vendedorCedula instanceof HTMLInputElement
        ? vendedorCedula.value
        : currentDraft.vendedorCedula,
    vendedorNombre:
      vendedorNombre instanceof HTMLInputElement
        ? vendedorNombre.value
        : currentDraft.vendedorNombre,
    vendedorInfo:
      vendedorInfo instanceof HTMLInputElement
        ? vendedorInfo.value
        : currentDraft.vendedorInfo,
    emisionContingencia:
      contingencia instanceof HTMLInputElement
        ? contingencia.checked
        : currentDraft.emisionContingencia,
    items,
  };
}

function applyClienteToFacturacionDraft(cliente) {
  const currentDraft = state.facturacion.draft || createEmptyFacturacionDraft();
  state.facturacion.draft = {
    ...currentDraft,
    clienteCodigo: cliente?.codigo || currentDraft.clienteCodigo,
    clienteNombre: cliente?.nombre || "",
    clienteInfo: cliente ? cliente.tipoNombre || cliente.telefono || "" : "",
    clienteTelefono: cliente?.telefono || "",
    clienteDireccion: cliente?.direccion || "",
  };
}

function clearFacturacionCliente() {
  const currentDraft = state.facturacion.draft || createEmptyFacturacionDraft();
  state.facturacion.draft = {
    ...currentDraft,
    clienteNombre: "",
    clienteInfo: "",
    clienteTelefono: "",
    clienteDireccion: "",
  };
}

function applyTrabajadorToFacturacionDraft(trabajador) {
  const currentDraft = state.facturacion.draft || createEmptyFacturacionDraft();
  state.facturacion.draft = {
    ...currentDraft,
    vendedorCedula: trabajador?.cedula || "",
    vendedorNombre: trabajador?.nombre || "",
    vendedorInfo: trabajador
      ? trabajador.cargoNombre || trabajador.cargo || ""
      : "",
  };
}

function clearFacturacionTrabajador() {
  const currentDraft = state.facturacion.draft || createEmptyFacturacionDraft();
  state.facturacion.draft = {
    ...currentDraft,
    vendedorNombre: "",
    vendedorInfo: "",
  };
}

function fillFacturacionLineFromInventory(index, article) {
  const currentDraft = normalizeFacturacionDraft(
    state.facturacion.draft || createEmptyFacturacionDraft(),
  );
  const items =
    Array.isArray(currentDraft.items) && currentDraft.items.length
      ? [...currentDraft.items]
      : createEmptyFacturacionItems();
  const currentLine = items[index] || createEmptyFacturacionLineDraft();
  const linePriceList = normalizeFacturacionPriceList(
    currentLine.priceList || currentDraft.priceList,
  );
  items[index] = buildFacturacionLineFromInventory(
    currentLine,
    article,
    linePriceList,
  );

  state.facturacion.draft = {
    ...currentDraft,
    items,
  };
}

function getFacturacionArticleExistence(article) {
  return toFacturacionNumber(
    article?.inventario?.existenciaActual ??
      article?.inventario?.existencia ??
      article?.existenciaActual ??
      article?.existencia ??
      "0",
  );
}

function facturacionArticleHasConfiguredCosts(article) {
  const costoInicial = toFacturacionNumber(
    article?.inventario?.costos?.inicial ?? article?.costoInicial ?? "0",
  );
  const costoPromedio = toFacturacionNumber(
    article?.inventario?.costos?.promedio ?? article?.costoPromedio ?? "0",
  );
  const ultimoCosto = toFacturacionNumber(
    article?.inventario?.costos?.ultimo ?? article?.ultimoCosto ?? "0",
  );

  return costoInicial > 0 || costoPromedio > 0 || ultimoCosto > 0;
}

function getFacturacionArticleValidationMessage(article) {
  const codigoBarra =
    String(article?.codigoBarra || "").trim() || "seleccionado";

  if (getFacturacionArticleExistence(article) <= 0) {
    return `El articulo ${codigoBarra} no se puede facturar porque no tiene existencia.`;
  }

  if (!facturacionArticleHasConfiguredCosts(article)) {
    return `Error sin precio. El articulo ${codigoBarra} no tiene costos configurados.`;
  }

  return "";
}

function clearFacturacionLine(index, keepCode = "") {
  const currentDraft = normalizeFacturacionDraft(
    state.facturacion.draft || createEmptyFacturacionDraft(),
  );
  const items =
    Array.isArray(currentDraft.items) && currentDraft.items.length
      ? [...currentDraft.items]
      : createEmptyFacturacionItems();

  items[index] = {
    ...createEmptyFacturacionLineDraft(),
    priceList: normalizeFacturacionPriceList(
      items[index]?.priceList || currentDraft.priceList,
    ),
    codigoBarra: keepCode,
  };

  state.facturacion.draft = {
    ...currentDraft,
    items,
  };
}

function facturacionLineHasContent(line) {
  const normalizedLine = normalizeFacturacionLineDraft(line);
  return Boolean(
    String(normalizedLine.codigoBarra || "").trim() ||
      String(normalizedLine.nombre || "").trim() ||
      String(normalizedLine.precio || "").trim() ||
      String(normalizedLine.subtotal || "").trim() ||
      String(normalizedLine.descuentoMonto || "").trim() ||
      String(normalizedLine.precioDetal || "").trim() ||
      String(normalizedLine.precioMayor || "").trim() ||
      String(normalizedLine.precioAfiliado || "").trim() ||
      toFacturacionNumber(normalizedLine.cantidad) > 0
  );
}

function removeFacturacionLine(index) {
  const currentDraft = normalizeFacturacionDraft(
    state.facturacion.draft || createEmptyFacturacionDraft(),
  );
  const items = normalizeFacturacionItems(currentDraft.items);
  if (!Number.isInteger(index) || index < 0 || index >= items.length) {
    return false;
  }

  const currentLine = normalizeFacturacionLineDraft(items[index]);
  if (!facturacionLineHasContent(currentLine)) {
    return false;
  }

  const compactedItems = items
    .filter((_, currentIndex) => currentIndex !== index)
    .filter((item) => facturacionLineHasContent(item));

  state.facturacion.draft = {
    ...currentDraft,
    items: normalizeFacturacionItems(compactedItems),
  };

  if (compactedItems.length) {
    state.facturacion.selectedLineIndex = Math.min(index, compactedItems.length - 1);
  } else {
    state.facturacion.selectedLineIndex = -1;
  }

  return true;
}

function resolveFacturacionPriceForList(source, priceList) {
  const normalizedPriceList = normalizeFacturacionPriceList(priceList);
  const prices = source?.precios || {};

  if (normalizedPriceList === "mayor") {
    return toFacturacionNumber(prices.mayor ?? source?.precioMayor ?? "0");
  }

  if (normalizedPriceList === "afiliado") {
    return toFacturacionNumber(
      prices.afiliado ?? source?.precioAfiliado ?? "0",
    );
  }

  return toFacturacionNumber(prices.detal ?? source?.precioDetal ?? "0");
}

function resolveFacturacionPromotionPercentage(source) {
  return toFacturacionNumber(
    source?.precios?.promocion?.porcentajeDescuento ??
      source?.porcentajeDescuento ??
      source?.descuentoPorcentaje ??
      "0",
  );
}

function resolveFacturacionPromotionActive(source) {
  return Boolean(
    source?.precios?.promocion?.activa ?? source?.promocionActiva ?? false,
  );
}

function resolveFacturacionPromotionPercentageForPriceList(source, priceList) {
  if (normalizeFacturacionPriceList(priceList) !== "detal") {
    return 0;
  }

  if (!resolveFacturacionPromotionActive(source)) {
    return 0;
  }

  return resolveFacturacionPromotionPercentage(source);
}

function recalculateFacturacionLineAmounts(line, options = {}) {
  const { defaultQuantity = "" } = options;
  const normalizedLine = normalizeFacturacionLineDraft(line);
  if (!String(normalizedLine.codigoBarra || "").trim()) {
    return normalizedLine;
  }

  const quantityInput =
    String(normalizedLine.cantidad || "").trim() ||
    String(defaultQuantity || "").trim();
  const quantity = Math.max(toFacturacionNumber(quantityInput || "0"), 0);
  const precio = toFacturacionNumber(normalizedLine.precio);
  const descuentoPorcentaje = Math.max(
    toFacturacionNumber(normalizedLine.descuentoPorcentaje),
    0,
  );
  const subtotal = roundToTwoDecimals(precio * quantity);
  const descuentoMonto = roundToTwoDecimals(
    subtotal * (descuentoPorcentaje / 100),
  );

  return {
    ...normalizedLine,
    cantidad: quantityInput,
    subtotal: formatTransferAmount(subtotal),
    descuentoMonto: formatTransferAmount(descuentoMonto),
  };
}

function buildFacturacionLineFromInventory(currentLine, article, priceList) {
  const normalizedPriceList = normalizeFacturacionPriceList(priceList);
  const precioDetal = resolveFacturacionPriceForList(article, "detal");
  const precioMayor = resolveFacturacionPriceForList(article, "mayor");
  const precioAfiliado = resolveFacturacionPriceForList(article, "afiliado");
  const precioBase = resolveFacturacionPriceForList(
    article,
    normalizedPriceList,
  );
  const descuentoPorcentaje = resolveFacturacionPromotionPercentageForPriceList(
    article,
    normalizedPriceList,
  );

  return recalculateFacturacionLineAmounts(
    {
      ...normalizeFacturacionLineDraft(currentLine),
      priceList: normalizedPriceList,
      codigoBarra: article.codigoBarra || currentLine.codigoBarra || "",
      nombre:
        article.general?.nombre || article.nombre || currentLine.nombre || "",
      precio: formatTransferAmount(precioBase),
      cantidad: "1",
      descuentoPorcentaje: formatTransferAmount(descuentoPorcentaje),
      precioDetal: formatTransferAmount(precioDetal),
      precioMayor: formatTransferAmount(precioMayor),
      precioAfiliado: formatTransferAmount(precioAfiliado),
      precioPromocion: formatTransferAmount(
        toFacturacionNumber(
          article?.precios?.promocion?.precio ?? article?.precioPromocion ?? "0",
        ),
      ),
      promocionActiva: resolveFacturacionPromotionActive(article),
    },
    { defaultQuantity: "1" },
  );
}

function recalculateFacturacionLineForPriceList(line, priceList) {
  const normalizedLine = normalizeFacturacionLineDraft(line);
  if (!String(normalizedLine.codigoBarra || "").trim()) {
    return normalizedLine;
  }

  const hasPriceSource = [
    normalizedLine.precioDetal,
    normalizedLine.precioMayor,
    normalizedLine.precioAfiliado,
  ].some((value) => String(value || "").trim());

  if (!hasPriceSource) {
    return normalizedLine;
  }

  const precioBase = resolveFacturacionPriceForList(normalizedLine, priceList);
  const descuentoPorcentaje = resolveFacturacionPromotionPercentageForPriceList(
    normalizedLine,
    priceList,
  );

  return recalculateFacturacionLineAmounts(
    {
      ...normalizedLine,
      precio: formatTransferAmount(precioBase),
      descuentoPorcentaje: formatTransferAmount(descuentoPorcentaje),
    },
    { defaultQuantity: "1" },
  );
}

function recalculateFacturacionDraftForPriceList(draft, priceList) {
  const normalizedDraft = normalizeFacturacionDraft({
    ...(draft || {}),
    priceList,
  });

  return {
    ...normalizedDraft,
    items: normalizedDraft.items.map((line) =>
      recalculateFacturacionLineForPriceList(line, normalizedDraft.priceList),
    ),
  };
}

function recalculateFacturacionDraftLinePriceList(draft, lineIndex, priceList) {
  const normalizedDraft = normalizeFacturacionDraft(draft);
  const items = normalizedDraft.items.map((line, index) => {
    if (index !== lineIndex) {
      return line;
    }

    return recalculateFacturacionLineForPriceList(
      {
        ...line,
        priceList: normalizeFacturacionPriceList(priceList),
      },
      priceList,
    );
  });

  return {
    ...normalizedDraft,
    items,
  };
}

function resolveFacturacionUsdRate(rows, exchangeRate) {
  const detailRate = toFacturacionNumber(exchangeRate?.rateBsPerUsd);
  const mayorRate = toFacturacionNumber(exchangeRate?.rateMayor);

  if (detailRate > 0) {
    return detailRate;
  }

  return mayorRate;
}

function calculateFacturacionSummary(
  items,
  activeTax = null,
  exchangeRate = null,
  draft = null,
) {
  const rows = (Array.isArray(items) ? items : []).map((item) =>
    recalculateFacturacionLineAmounts(item),
  );
  const valorMercancia = rows.reduce(
    (sum, item) => sum + toFacturacionNumber(item?.subtotal),
    0,
  );
  const lineDiscountMonto = rows.reduce(
    (sum, item) => sum + toFacturacionNumber(item?.descuentoMonto),
    0,
  );
  const discountOverride = resolveFacturacionDiscountOverride(draft);
  const descuentoMonto = discountOverride.active
    ? valorMercancia * (discountOverride.percent / 100)
    : lineDiscountMonto;
  const subtotal = Math.max(valorMercancia - descuentoMonto, 0);
  const impuestoPorcentaje = 0;
  const impuestoMonto = 0;
  const rateBsPerUsd = resolveFacturacionUsdRate(rows, exchangeRate);
  const totalUnidades = rows.reduce((sum, item) => {
    if (!String(item?.codigoBarra || "").trim()) {
      return sum;
    }

    return sum + Math.max(toFacturacionNumber(item?.cantidad || "0"), 0);
  }, 0);
  const descuentoPorcentaje = discountOverride.active
    ? discountOverride.percent
    : getFacturacionLoadedArticleDiscountPercentage(rows);
  const totalVenta = subtotal;
  const totalUsd =
    rateBsPerUsd > 0 ? roundToTwoDecimals(totalVenta / rateBsPerUsd) : 0;

  return {
    valorMercancia,
    descuentoMonto,
    descuentoPorcentaje,
    subtotal,
    impuestoPorcentaje,
    impuestoMonto,
    rateBsPerUsd,
    totalUnidades,
    totalVenta,
    totalUsd,
    valorMercanciaDisplay: formatTransferAmount(valorMercancia),
    descuentoMontoDisplay: formatTransferAmount(descuentoMonto),
    descuentoPorcentajeDisplay: formatTransferAmount(descuentoPorcentaje),
    subtotalDisplay: formatTransferAmount(subtotal),
    impuestoPorcentajeDisplay: formatTransferAmount(impuestoPorcentaje),
    impuestoMontoDisplay: formatTransferAmount(impuestoMonto),
    totalUnidadesDisplay: formatTransferAmount(totalUnidades),
    totalVentaDisplay: formatTransferAmount(totalVenta),
    totalUsdDisplay: formatFacturacionUsdAmount(totalUsd),
  };
}

function getFacturacionLoadedArticleDiscountPercentage(items) {
  const rows = Array.isArray(items) ? items : [];

  for (let index = rows.length - 1; index >= 0; index -= 1) {
    const item = rows[index];
    if (!String(item?.codigoBarra || "").trim()) {
      continue;
    }

    return toFacturacionNumber(item?.descuentoPorcentaje);
  }

  return 0;
}

function buildFacturacionFrozenStorageKey() {
  const userCode =
    String(state.user?.codUsuario || "anon")
      .trim()
      .toUpperCase() || "ANON";
  return `${FACTURACION_FROZEN_STORAGE_KEY}.${userCode}`;
}

function generateFacturacionFrozenId() {
  return `frozen-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

function facturacionDraftHasContent(draft) {
  const normalizedDraft = normalizeFacturacionDraft(draft);
  if (
    normalizedDraft.clienteCodigo ||
    normalizedDraft.clienteNombre ||
    normalizedDraft.vendedorCedula ||
    normalizedDraft.vendedorNombre
  ) {
    return true;
  }

  return normalizedDraft.items.some((item) => {
    return [item.codigoBarra, item.nombre, item.precio].some((value) =>
      String(value || "").trim(),
    );
  });
}

function readStoredFacturacionFrozenDrafts() {
  try {
    const raw = window.localStorage.getItem(buildFacturacionFrozenStorageKey());
    if (!raw) {
      return [];
    }

    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) {
      return [];
    }

    return parsed
      .map((item) => ({
        id: String(item?.id || "").trim() || generateFacturacionFrozenId(),
        savedAt: String(item?.savedAt || "").trim() || new Date().toISOString(),
        draft: normalizeFacturacionDraft(item?.draft),
        exchangeRate: normalizeFacturacionExchangeRateState(item?.exchangeRate),
      }))
      .sort(
        (left, right) =>
          new Date(right.savedAt).getTime() - new Date(left.savedAt).getTime(),
      );
  } catch (error) {
    console.error(error);
    return [];
  }
}

function writeStoredFacturacionFrozenDrafts(records) {
  try {
    window.localStorage.setItem(
      buildFacturacionFrozenStorageKey(),
      JSON.stringify(Array.isArray(records) ? records : []),
    );
  } catch (error) {
    console.error(error);
  }
}

function openFacturacionDiscountAuthModal() {
  state.facturacion.discountAuth = {
    open: true,
    submitting: false,
    usuario: "",
    password: "",
  };
}

function closeFacturacionDiscountAuthModal() {
  state.facturacion.discountAuth = createEmptyFacturacionDiscountAuthState();
}

function captureFacturacionDiscountAuthDraft() {
  const form = document.getElementById("facturacion-discount-auth-form");
  if (!(form instanceof HTMLFormElement)) {
    return;
  }

  state.facturacion.discountAuth = {
    ...state.facturacion.discountAuth,
    usuario: readFormFieldValue(
      form,
      "usuario",
      state.facturacion.discountAuth.usuario,
    ),
    password: readFormFieldValue(
      form,
      "password",
      state.facturacion.discountAuth.password,
    ),
  };
}

function focusFacturacionGlobalDiscountInput() {
  render();
  queueMicrotask(() => {
    const input = document.querySelector("[data-facturacion-global-discount]");
    if (!(input instanceof HTMLInputElement)) {
      return;
    }

    input.focus();
    input.select?.();
  });
}

async function authorizeFacturacionGlobalDiscount() {
  const authDraft =
    state.facturacion.discountAuth || createEmptyFacturacionDiscountAuthState();
  const usuario = String(authDraft.usuario || "").trim();
  const password = String(authDraft.password || "").trim();

  if (!usuario || !password) {
    setFlash("Debes indicar usuario y clave de administrador.", "error");
    render();
    return;
  }

  state.facturacion.discountAuth = {
    ...authDraft,
    submitting: true,
  };
  clearFlash();
  render();

  try {
    const response = await apiFetch("/auth/login", {
      method: "POST",
      auth: false,
      body: {
        usuario,
        password,
      },
    });

    const authorizedUser = response?.usuario || null;
    if (!canAuthorizeFacturacionGlobalDiscount(authorizedUser)) {
      throw new Error(
        "Debes usar un usuario administrador para autorizar el descuento global.",
      );
    }

    const currentDraft = normalizeFacturacionDraft(state.facturacion.draft);
    const currentSummary = calculateFacturacionSummary(
      currentDraft.items,
      getActiveFacturacionTax(),
      state.facturacion.exchangeRate,
      currentDraft,
    );

    state.facturacion.draft = {
      ...currentDraft,
      overrideDiscountAuthorized: true,
      overrideDiscountPercent:
        currentDraft.overrideDiscountPercent ||
        currentSummary.descuentoPorcentajeDisplay,
    };

    closeFacturacionDiscountAuthModal();
    setFlash(
      `Descuento global autorizado por ${authorizedUser?.codUsuario || usuario}.`,
      "success",
    );
    focusFacturacionGlobalDiscountInput();
  } catch (error) {
    console.error(error);
    state.facturacion.discountAuth = {
      ...authDraft,
      submitting: false,
    };
    setFlash(extractErrorMessage(error), "error");
    render();
  }
}

function applyFacturacionGlobalDiscountFromField(value) {
  const currentDraft = normalizeFacturacionDraft(state.facturacion.draft);
  if (!currentDraft.overrideDiscountAuthorized) {
    return;
  }

  const rawValue = String(value || "").trim();
  if (!rawValue) {
    state.facturacion.draft = {
      ...currentDraft,
      overrideDiscountActive: false,
      overrideDiscountPercent: "",
    };
    clearFlash();
    render();
    return;
  }

  const discountPercent = toFacturacionNumber(rawValue);
  if (
    !Number.isFinite(discountPercent) ||
    discountPercent < 0 ||
    discountPercent > 100
  ) {
    setFlash("El descuento global debe estar entre 0 y 100.", "error");
    render();
    return;
  }

  state.facturacion.draft = {
    ...currentDraft,
    overrideDiscountActive: true,
    overrideDiscountPercent: formatTransferAmount(discountPercent),
  };
  clearFlash();
  render();
}

function openFacturacionFrozenLookupModal() {
  state.facturacion.frozenLookup = {
    open: true,
    items: readStoredFacturacionFrozenDrafts(),
  };
}

function closeFacturacionFrozenLookupModal() {
  state.facturacion.frozenLookup = createEmptyFacturacionFrozenLookupState();
}

async function openFacturacionPaymentModal() {
  if (!Array.isArray(state.tiposPago?.items) || !state.tiposPago.items.length) {
    try {
      await loadTiposPago({ renderAfter: false });
    } catch (error) {
      console.error(error);
    }
  }

  try {
    const bancosResponse = await apiFetch("/bancos?status=1&limit=100");
    state.facturacion.paymentBankOptions = Array.isArray(bancosResponse?.bancos)
      ? bancosResponse.bancos
      : [];
  } catch (error) {
    console.error(error);
    state.facturacion.paymentBankOptions = [];
  }

  try {
    await loadCashRegisters({ renderAfter: false });
  } catch (error) {
    console.error(error);
  }

  if (!getCloseableCashRegisters().length) {
    setFlash("Debes abrir una caja antes de facturar.", "error");
    render();
    return;
  }

  state.facturacion.paymentModal = {
    ...createEmptyFacturacionPaymentModalState(),
    ...state.facturacion.paymentModal,
    open: true,
    rows: normalizeFacturacionPaymentRows(state.facturacion.paymentModal?.rows),
  };
  state.facturacion.paymentCedulaPrompt =
    createEmptyFacturacionPaymentCedulaPromptState();
}

function closeFacturacionPaymentModal() {
  state.facturacion.paymentModal = {
    ...createEmptyFacturacionPaymentModalState(),
    rows: normalizeFacturacionPaymentRows(state.facturacion.paymentModal?.rows),
    open: false,
  };
  state.facturacion.paymentCedulaPrompt =
    createEmptyFacturacionPaymentCedulaPromptState();
}

function updateFacturacionPaymentField(rowIndex, fieldName, value) {
  const current =
    state.facturacion.paymentModal || createEmptyFacturacionPaymentModalState();
  const rows = normalizeFacturacionPaymentRows(current.rows).map(
    (row, index) => {
      if (index !== rowIndex) {
        return row;
      }

      return normalizeFacturacionPaymentRow(
        {
          ...row,
          [fieldName]: value,
        },
        index,
      );
    },
  );

  state.facturacion.paymentModal = {
    ...current,
    rows,
  };
}

function rerenderFacturacionPaymentField(rowIndex, fieldName) {
  render();
  window.setTimeout(() => {
    const selector = `[data-facturacion-payment-field="${fieldName}"][data-facturacion-payment-row="${rowIndex}"]`;
    const field = document.querySelector(selector);
    if (field instanceof HTMLInputElement) {
      field.focus();
      const cursorAt = field.value.length;
      field.setSelectionRange(cursorAt, cursorAt);
      return;
    }

    if (field instanceof HTMLSelectElement) {
      field.focus();
    }
  }, 0);
}

function openFacturacionPaymentCedulaPrompt(rowIndex) {
  state.facturacion.paymentCedulaPrompt = {
    open: true,
    rowIndex,
  };
}

function closeFacturacionPaymentCedulaPrompt(options = {}) {
  const { focusRowIndex = null } = options;
  state.facturacion.paymentCedulaPrompt =
    createEmptyFacturacionPaymentCedulaPromptState();

  if (Number.isInteger(focusRowIndex) && focusRowIndex >= 0) {
    window.setTimeout(() => {
      const field = document.querySelector(
        `[data-facturacion-payment-cedula="${focusRowIndex}"]`,
      );
      if (field instanceof HTMLInputElement) {
        field.focus();
        field.select();
      }
    }, 0);
  }
}

function applyFacturacionPaymentClientCedula(rowIndex) {
  const clientCedula = String(
    state.facturacion.draft?.clienteCodigo || "",
  ).trim();
  if (!clientCedula) {
    closeFacturacionPaymentCedulaPrompt({ focusRowIndex: rowIndex });
    setFlash(
      "Primero debes cargar la cedula del cliente en la factura.",
      "error",
    );
    render();
    return;
  }

  updateFacturacionPaymentField(rowIndex, "cedula", clientCedula);
  closeFacturacionPaymentCedulaPrompt({ focusRowIndex: rowIndex });
}

function parseFacturacionPaymentAmount(value) {
  const parsed = parseExchangeRateNumber(value);
  return parsed === null ? 0 : parsed;
}

function facturacionPaymentMethodUsesUsdAmount(method) {
  const normalized = normalizeFacturacionPaymentMethod(method);
  return ["EFECTIVO DOLAR", "USDT", "DOLAR ELECTRONICO"].includes(normalized);
}

function resolveFacturacionPaymentAmountInBs(row, rateBsPerUsd = 0) {
  const amount = parseFacturacionPaymentAmount(row?.monto);
  if (amount <= 0) {
    return 0;
  }

  if (facturacionPaymentMethodUsesUsdAmount(row?.formaPago)) {
    const rate = toFacturacionNumber(rateBsPerUsd);
    if (rate <= 0) {
      return 0;
    }

    return roundToTwoDecimals(amount * rate);
  }

  return amount;
}

function facturacionPaymentMethodAppliesIgtf(method) {
  return false;
}

function validateFacturacionPaymentRows(summary, rows) {
  const paymentRows = normalizeFacturacionPaymentRows(rows);
  const hasAnyAmount = paymentRows.some(
    (row) => parseFacturacionPaymentAmount(row?.monto) > 0,
  );
  if (!hasAnyAmount) {
    return "Debes indicar al menos un monto en la forma de pago.";
  }

  const hasUsdPayment = paymentRows.some((row) => {
    return (
      facturacionPaymentMethodUsesUsdAmount(row?.formaPago) &&
      parseFacturacionPaymentAmount(row?.monto) > 0
    );
  });
  if (hasUsdPayment && toFacturacionNumber(summary?.rateBsPerUsd) <= 0) {
    return "No hay una tasa de cambio vigente para convertir el efectivo en dolares.";
  }

  const amountWithoutMethod = paymentRows.find((row) => {
    return (
      parseFacturacionPaymentAmount(row?.monto) > 0 &&
      !normalizeFacturacionPaymentMethod(row?.formaPago)
    );
  });
  if (amountWithoutMethod) {
    return "Cada monto cargado debe tener una forma de pago seleccionada.";
  }

  const paymentSummary = calculateFacturacionPaymentSummary(
    summary,
    paymentRows,
  );
  const paymentExceeded = roundToTwoDecimals(
    paymentSummary.abonado - paymentSummary.total,
  );
  if (paymentExceeded > 0.009) {
    return "No se puede proceder porque el monto pagado es mayor al total de la venta.";
  }

  const paymentPending = roundToTwoDecimals(
    paymentSummary.total - paymentSummary.abonado,
  );
  if (paymentPending > 0.009) {
    return "Los pagos cargados aun no cubren el total de la venta.";
  }

  return "";
}

function freezeCurrentFacturacionDraft() {
  const currentDraft = normalizeFacturacionDraft(
    state.facturacion.draft || createEmptyFacturacionDraft(),
  );
  if (!facturacionDraftHasContent(currentDraft)) {
    setFlash("No hay una factura en curso para congelar.", "error");
    render();
    return;
  }

  const frozenId = currentDraft.frozenId || generateFacturacionFrozenId();
  const savedAt = new Date().toISOString();
  const record = {
    id: frozenId,
    savedAt,
    draft: normalizeFacturacionDraft({
      ...currentDraft,
      frozenId,
    }),
    exchangeRate: normalizeFacturacionExchangeRateState(
      state.facturacion.exchangeRate,
    ),
  };

  const existing = readStoredFacturacionFrozenDrafts().filter(
    (item) => item.id !== frozenId,
  );
  writeStoredFacturacionFrozenDrafts([record, ...existing]);

  state.facturacion.draft = normalizeFacturacionDraft({
    priceList: currentDraft.priceList,
  });
  state.facturacion.selectedLineIndex = -1;
  state.facturacion.discountAuth = createEmptyFacturacionDiscountAuthState();
  state.facturacion.lookup = {
    open: false,
    loading: false,
    type: "",
    items: [],
  };
  state.facturacion.paymentModal = createEmptyFacturacionPaymentModalState();
  state.facturacion.paymentCedulaPrompt =
    createEmptyFacturacionPaymentCedulaPromptState();
  closeFacturacionLineLookupModal();
  closeFacturacionFrozenLookupModal();
  closeFacturacionClientEditor();
  setFlash(
    `Factura congelada correctamente (${formatDateDisplay(savedAt)}).`,
    "success",
  );
  render();
}

function getFacturacionResumeFocusRow(draft) {
  const items = Array.isArray(draft?.items) ? draft.items : [];
  const lastFilledIndex = items.reduce((lastIndex, item, index) => {
    return String(item?.codigoBarra || "").trim() ? index : lastIndex;
  }, -1);

  if (lastFilledIndex < 0) {
    return 1;
  }

  return Math.min(lastFilledIndex + 2, items.length || 1);
}

async function restoreFacturacionFrozenDraft(recordId) {
  const records = readStoredFacturacionFrozenDrafts();
  const selected = records.find((item) => item.id === recordId);
  if (!selected) {
    setFlash("La factura congelada seleccionada ya no existe.", "error");
    render();
    return;
  }

  const storedExchangeRate = normalizeFacturacionExchangeRateState(
    selected.exchangeRate,
  );
  writeStoredFacturacionFrozenDrafts(
    records.filter((item) => item.id !== recordId),
  );
  state.facturacion.draft = normalizeFacturacionDraft(selected.draft);
  state.facturacion.exchangeRate = storedExchangeRate;
  state.facturacion.selectedLineIndex = -1;
  closeFacturacionFrozenLookupModal();

  try {
    await loadFacturacionExchangeRate({ renderAfter: false, silent: true });
  } catch (_error) {
    state.facturacion.exchangeRate = storedExchangeRate;
  }

  const currentRate = toFacturacionNumber(
    state.facturacion.exchangeRate?.rateBsPerUsd,
  );
  const storedRate = toFacturacionNumber(storedExchangeRate?.rateBsPerUsd);
  const rateMessage =
    currentRate > 0 && currentRate !== storedRate
      ? ` Se aplico la nueva tasa ${formatExchangeRateAmount(currentRate)}.`
      : currentRate > 0
        ? ` Se aplico la tasa actual ${formatExchangeRateAmount(currentRate)}.`
        : "";

  setFlash(`Factura descongelada correctamente.${rateMessage}`, "success");
  renderFacturacionAndFocusLine(getFacturacionResumeFocusRow(selected.draft));
}

