function readFormFieldValue(form, fieldName, fallback = "") {
  const field = form?.elements?.namedItem?.(fieldName);
  if (!field || !("value" in field)) {
    return fallback;
  }

  return field.value;
}

function readRadioValue(form, fieldName, fallback = "") {
  const checkedField = form?.querySelector?.(
    `input[name="${fieldName}"]:checked`,
  );
  if (checkedField && "value" in checkedField) {
    return checkedField.value;
  }

  const firstField = form?.querySelector?.(`input[name="${fieldName}"]`);
  if (firstField && "value" in firstField) {
    return firstField.value || fallback;
  }

  return fallback;
}
function readFormCheckboxValue(form, fieldName, fallback = false) {
  const field = form?.elements?.namedItem?.(fieldName);
  if (!field || !("checked" in field)) {
    return fallback;
  }

  return Boolean(field.checked);
}

function createCatalogManualDraft(kind) {
  const config = getCatalogImportConfig(kind);
  const supportsStatus = config?.columns?.some(
    (column) => column.key === "status",
  );

  return {
    codigo: "",
    nombre: "",
    status: supportsStatus ? "1" : "",
  };
}

function getCatalogManualDraft(kind) {
  const existingDraft = state.catalogImport.manualDraftsByKind?.[kind];
  if (existingDraft) {
    return existingDraft;
  }

  const createdDraft = createCatalogManualDraft(kind);
  state.catalogImport.manualDraftsByKind = {
    ...(state.catalogImport.manualDraftsByKind || {}),
    [kind]: createdDraft,
  };
  return createdDraft;
}

function readCatalogManualDraft(form, kind) {
  const config = getCatalogImportConfig(kind);
  const supportsStatus = config?.columns?.some(
    (column) => column.key === "status",
  );

  return {
    codigo: readFormFieldValue(form, "codigo", ""),
    nombre: readFormFieldValue(form, "nombre", ""),
    status: supportsStatus ? readFormFieldValue(form, "status", "1") : "",
  };
}

function validateCatalogManualDraft(kind, draft) {
  const config = getCatalogImportConfig(kind);
  if (!config) {
    return "Catalogo no valido.";
  }

  const supportsName = config.columns.some((column) => column.key === "nombre");
  const codigo = String(draft.codigo || "").trim();
  const nombre = String(draft.nombre || "").trim();
  const catalogLabel = getCatalogSingularLabel(config.singular);

  if (!supportsName && !codigo) {
    return `Debes indicar el codigo de ${catalogLabel}.`;
  }

  if (supportsName && !nombre) {
    return `Debes indicar el nombre de ${catalogLabel}.`;
  }

  if (codigo && config.maxCodeLength && codigo.length > config.maxCodeLength) {
    return `El codigo de ${catalogLabel} no puede tener mas de ${config.maxCodeLength} caracteres.`;
  }

  if (
    supportsName &&
    nombre &&
    config.maxNameLength &&
    nombre.length > config.maxNameLength
  ) {
    return `El nombre de ${catalogLabel} no puede tener mas de ${config.maxNameLength} caracteres.`;
  }

  return "";
}

function buildCatalogManualPayload(kind, draft) {
  const config = getCatalogImportConfig(kind);
  const supportsStatus = config?.columns?.some(
    (column) => column.key === "status",
  );

  return {
    codigo: String(draft.codigo || "").trim() || undefined,
    nombre: String(draft.nombre || "").trim() || undefined,
    status: supportsStatus
      ? Number.parseInt(String(draft.status || "1"), 10)
      : undefined,
  };
}

async function loadCatalogImportItems(kind, options = {}) {
  const normalizedKind = String(kind || "")
    .trim()
    .toLowerCase();
  const { renderAfter = true } = options;

  if (!normalizedKind) {
    return;
  }

  state.catalogImport.loadingKind = normalizedKind;
  if (renderAfter) {
    render();
  }

  try {
    const response = await apiFetch(
      `/inventory/catalogs/${encodeURIComponent(normalizedKind)}`,
    );
    const items = Array.isArray(response?.items) ? response.items : [];

    state.catalogImport.itemsByKind = {
      ...(state.catalogImport.itemsByKind || {}),
      [normalizedKind]: items,
    };

    if (state.metadata?.catalogos) {
      state.metadata.catalogos = {
        ...state.metadata.catalogos,
        [normalizedKind]: items,
      };
    }
  } catch (error) {
    console.error(error);
    setFlash(
      `No se pudo cargar el catalogo: ${extractErrorMessage(error)}`,
      "error",
    );
  } finally {
    if (state.catalogImport.loadingKind === normalizedKind) {
      state.catalogImport.loadingKind = "";
    }

    if (renderAfter) {
      render();
    }
  }
}

async function importCatalogExcel(kind, file) {
  const normalizedKind = String(kind || "")
    .trim()
    .toLowerCase();

  if (!normalizedKind || !file) {
    return;
  }

  state.catalogImport.uploadingKind = normalizedKind;
  clearFlash();
  render();

  try {
    const formData = new FormData();
    formData.append("file", file);

    await apiFetch(`/inventory/catalogs/import/${encodeURIComponent(normalizedKind)}`, {
      method: "POST",
      body: formData,
    });

    await loadCreationMetadata({ renderAfter: false });
    await loadCatalogImportItems(normalizedKind, { renderAfter: false });
    setFlash("Catalogo importado correctamente.", "success");
  } catch (error) {
    console.error(error);
    setFlash(extractErrorMessage(error), "error");
  } finally {
    if (state.catalogImport.uploadingKind === normalizedKind) {
      state.catalogImport.uploadingKind = "";
    }
    render();
  }
}

async function saveCatalogManualEntry(kind) {
  const normalizedKind = String(kind || "")
    .trim()
    .toLowerCase();
  const draft = getCatalogManualDraft(normalizedKind);
  const validationMessage = validateCatalogManualDraft(normalizedKind, draft);
  const config = getCatalogImportConfig(normalizedKind);

  if (!normalizedKind || !config) {
    return;
  }

  if (validationMessage) {
    setFlash(validationMessage, "error");
    render();
    return;
  }

  state.catalogImport.manualSubmittingKind = normalizedKind;
  clearFlash();
  render();

  try {
    await apiFetch(`/inventory/catalogs/${encodeURIComponent(normalizedKind)}`, {
      method: "POST",
      body: buildCatalogManualPayload(normalizedKind, draft),
    });

    state.catalogImport.manualDraftsByKind = {
      ...(state.catalogImport.manualDraftsByKind || {}),
      [normalizedKind]: createCatalogManualDraft(normalizedKind),
    };

    await loadCreationMetadata({ renderAfter: false });
    await loadCatalogImportItems(normalizedKind, { renderAfter: false });
    setFlash(
      `${capitalize(config.singular)} guardado correctamente.`,
      "success",
    );
  } catch (error) {
    console.error(error);
    setFlash(extractErrorMessage(error), "error");
  } finally {
    if (state.catalogImport.manualSubmittingKind === normalizedKind) {
      state.catalogImport.manualSubmittingKind = "";
    }
    render();
  }
}

async function deleteCatalogEntry(kind, code) {
  const normalizedKind = String(kind || "")
    .trim()
    .toLowerCase();
  const normalizedCode = String(code || "").trim();

  if (!normalizedKind || !normalizedCode) {
    return;
  }

  const confirmed = window.confirm(
    `Se eliminara el registro ${normalizedCode}. Deseas continuar?`,
  );
  if (!confirmed) {
    return;
  }

  const deleteKey = buildCatalogEntryDeleteKey(normalizedKind, normalizedCode);
  state.catalogImport.deletingEntryKey = deleteKey;
  clearFlash();
  render();

  try {
    await apiFetch(
      `/inventory/catalogs/${encodeURIComponent(normalizedKind)}/${encodeURIComponent(normalizedCode)}`,
      {
        method: "DELETE",
      },
    );

    await loadCreationMetadata({ renderAfter: false });
    await loadCatalogImportItems(normalizedKind, { renderAfter: false });
    setFlash("Registro eliminado correctamente.", "success");
  } catch (error) {
    console.error(error);
    setFlash(extractErrorMessage(error), "error");
  } finally {
    if (state.catalogImport.deletingEntryKey === deleteKey) {
      state.catalogImport.deletingEntryKey = "";
    }
    render();
  }
}

function getCatalogSingularLabel(singular) {
  if (
    ["categoria", "marca", "talla"].includes(
      String(singular || "").toLowerCase(),
    )
  ) {
    return `la ${singular}`;
  }

  return `el ${singular}`;
}

function syncExistenceAutoRefresh() {
  if (typeof window === "undefined") {
    return;
  }

  if (!state.token || state.currentView !== "existencia") {
    clearExistenceAutoRefresh();
    return;
  }

  if (existenceAutoRefreshHandle !== null) {
    return;
  }

  existenceAutoRefreshHandle = window.setInterval(async () => {
    if (!state.token || state.currentView !== "existencia") {
      clearExistenceAutoRefresh();
      return;
    }

    if (
      state.inventoryExistence.loading ||
      state.inventoryExistence.refreshing
    ) {
      return;
    }

    await loadInventoryExistence(
      state.inventoryExistence.pagination.page || 1,
      {
        background: true,
      },
    );
  }, EXISTENCE_AUTO_REFRESH_MS);
}

function clearExistenceAutoRefresh() {
  if (existenceAutoRefreshHandle === null || typeof window === "undefined") {
    return;
  }

  window.clearInterval(existenceAutoRefreshHandle);
  existenceAutoRefreshHandle = null;
}

async function preloadAuthenticatedDesktopData() {
  if (!userCanAccessFullInventory()) {
    state.metadata = null;
    state.articles = [];
    state.inventoryExistence.items = [];
    state.inventoryExistence.lastUpdatedAt = "";
    state.inventoryExistence.pagination = {
      page: 1,
      limit: 25,
      total: 0,
      totalPages: 0,
    };
    state.pagination = {
      page: 1,
      limit: 10,
      total: 0,
      totalPages: 0,
    };
    return;
  }

  await Promise.all([
    loadCreationMetadata({ renderAfter: false }),
    loadArticles(1, { renderAfter: false }),
  ]);
}

function isCatalogImportView(view) {
  return ["categorias", "marcas", "tallas", "colores", "fabricantes"].includes(
    view,
  );
}

function buildCatalogEntryDeleteKey(kind, code) {
  return `${String(kind || "")
    .trim()
    .toLowerCase()}:${String(code || "")
    .trim()
    .toUpperCase()}`;
}

function normalizeSearchText(value) {
  return String(value || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .trim()
    .toLowerCase();
}

function normalizeGroupCode(value) {
  const aliases = {
    ADMIN: "ADMI",
    ADMINISTRADOR: "ADMI",
    ADMI: "ADMI",
    CAJE: "CAJA",
    CAJA: "CAJA",
  };
  const normalized = String(value || "")
    .trim()
    .toUpperCase();
  return aliases[normalized] || normalized;
}

function getCurrentUserGroupCodes() {
  if (!Array.isArray(state.user?.grupos)) {
    return [];
  }

  return state.user.grupos.map((group) =>
    normalizeGroupCode(group.codigo || group.nombre || ""),
  );
}

function getCurrentUserPermissionCodes() {
  if (!Array.isArray(state.user?.permisos)) {
    return [];
  }

  return state.user.permisos
    .map((permission) =>
      String(permission || "")
        .trim()
        .toUpperCase(),
    )
    .filter(Boolean);
}

function userCanAccessFullInventory() {
  const groups = getCurrentUserGroupCodes();
  return groups.includes("ADMI") || groups.includes("SISTEMA");
}

function userCanManageAllModules() {
  const groups = getCurrentUserGroupCodes();
  return groups.includes("ADMI") || groups.includes("SISTEMA");
}

function userIsCashierOperator() {
  return getCurrentUserGroupCodes().includes("CAJA");
}

function userCanCreateArticlesInCurrentInstance() {
  return Boolean(state.metadata?.contexto?.puedeCrearArticulos);
}

function userIsSystemOperator() {
  return getCurrentUserGroupCodes().includes("SISTEMA");
}

function userCanAccessView(view) {
  const normalizedView = String(view || "desktop")
    .trim()
    .toLowerCase();

  if (userCanManageAllModules()) {
    return true;
  }

  if (userIsCashierOperator()) {
    return ["desktop", "facturacion", "cajas", "cierre-caja", "ayuda"].includes(
      normalizedView,
    );
  }

  return true;
}

function userCanImportCatalogsFromExcel() {
  return getCurrentUserPermissionCodes().includes(
    CATALOG_IMPORT_EXCEL_PERMISSION_CODE,
  );
}

function roleHasCatalogImportPermission(role) {
  return (
    Array.isArray(role?.permisos) &&
    role.permisos.some(
      (permission) =>
        String(permission?.codigo || "").toUpperCase() ===
        CATALOG_IMPORT_EXCEL_PERMISSION_CODE,
    )
  );
}

function renderFlash() {
  if (!state.flash?.message) {
    return "";
  }

  return `
    <div class="flash flash-${escapeHtml(state.flash.type || "info")}">
      <span class="flash-message">${escapeHtml(state.flash.message)}</span>
      <button class="flash-dismiss" type="button" data-dismiss-flash aria-label="Cerrar alerta">
        &times;
      </button>
    </div>
  `;
}

function bindFlashEvents() {
  document.querySelectorAll("[data-dismiss-flash]").forEach((button) => {
    button.addEventListener("click", () => {
      clearFlash();
      render();
    });
  });
}

function renderSelectOptions(options, selectedValue) {
  return options
    .map((option) => {
      const isSelected = option.value === selectedValue;
      return `
        <option value="${escapeHtml(option.value)}" ${isSelected ? "selected" : ""}>
          ${escapeHtml(option.label)}
        </option>
      `;
    })
    .join("");
}

function renderTaxOptions(options, selectedValue) {
  const normalizedSelectedValue = String(selectedValue || "");
  if (!options.length) {
    return normalizedSelectedValue
      ? `<option value="${escapeHtml(normalizedSelectedValue)}" selected>${escapeHtml(normalizedSelectedValue)}</option>`
      : `<option value="" selected>Selecciona un impuesto</option>`;
  }

  const renderedOptions = options
    .map((option) => {
      const optionValue = String(option.codigo);
      const labelParts = [option.codigo, option.nombre].filter(Boolean);
      if (option.porcentajeImpuesto) {
        labelParts.push(`${option.porcentajeImpuesto}%`);
      }

      return `
        <option value="${escapeHtml(optionValue)}" ${optionValue === normalizedSelectedValue ? "selected" : ""}>
          ${escapeHtml(labelParts.join(" - "))}
        </option>
      `;
    })
    .join("");

  if (!normalizedSelectedValue) {
    return `<option value="" selected>Selecciona un impuesto</option>${renderedOptions}`;
  }

  return renderedOptions;
}

async function apiFetch(path, options = {}) {
  const headers = new Headers(options.headers || {});
  const isFormData =
    typeof FormData !== "undefined" && options.body instanceof FormData;
  headers.set("Accept", "application/json");

  if (options.body !== undefined && !isFormData) {
    headers.set("Content-Type", "application/json");
  }

  if (options.auth !== false && state.token) {
    headers.set("Authorization", `Bearer ${state.token}`);
  }

  const response = await window.fetch(`${API_BASE}${path}`, {
    method: options.method || "GET",
    headers,
    body:
      options.body !== undefined
        ? isFormData
          ? options.body
          : JSON.stringify(options.body)
        : undefined,
  });

  const payload = await readResponsePayload(response);

  if (!response.ok) {
    const error = new Error(
      extractMessageFromPayload(payload) || `Error ${response.status}`,
    );
    error.status = response.status;
    error.payload = payload;

    if (response.status === 401 && options.auth !== false) {
      clearSession();
      setFlash("La sesion expiro. Vuelve a iniciar sesion.", "error");
      render();
    }

    throw error;
  }

  return payload;
}

async function readResponsePayload(response) {
  if (response.status === 204) {
    return null;
  }

  const contentType = response.headers.get("content-type") || "";
  if (contentType.includes("application/json")) {
    return response.json();
  }

  return response.text();
}

function extractMessageFromPayload(payload) {
  if (!payload) {
    return "";
  }

  if (typeof payload === "string") {
    return payload;
  }

  if (Array.isArray(payload?.message)) {
    return payload.message.join(". ");
  }

  if (typeof payload?.message === "string") {
    return payload.message;
  }

  if (typeof payload?.error === "string") {
    return payload.error;
  }

  return "";
}

function extractErrorMessage(error) {
  return error?.message || "Ocurrio un error inesperado.";
}

function extractArticleConflictMessage(error) {
  const message = extractErrorMessage(error);
  if (!message) {
    return "Ya existe un conflicto con los datos del articulo.";
  }

  if (message.toLowerCase().includes("codigo de barra")) {
    return "Ya existe un articulo con ese codigo de barra.";
  }

  if (
    message.toLowerCase().includes("misma referencia") ||
    message.toLowerCase().includes("referencia")
  ) {
    return "Ya existe un articulo con esa referencia dentro de la misma marca.";
  }

  return message;
}

function setFlash(message, type = "info") {
  state.flash = { message, type };
  scheduleFlashAutoDismiss();
}

function clearFlash() {
  if (flashAutoDismissHandle) {
    window.clearTimeout(flashAutoDismissHandle);
    flashAutoDismissHandle = null;
  }
  state.flash = null;
}

function scheduleFlashAutoDismiss() {
  if (flashAutoDismissHandle) {
    window.clearTimeout(flashAutoDismissHandle);
    flashAutoDismissHandle = null;
  }

  if (!state.flash?.message) {
    return;
  }

  flashAutoDismissHandle = window.setTimeout(() => {
    flashAutoDismissHandle = null;
    if (!state.flash?.message) {
      return;
    }
    clearFlash();
    render();
  }, FLASH_AUTO_DISMISS_MS);
}

function persistSession() {
  const persistent = shouldPersistSession();
  const targetStorage = persistent
    ? window.localStorage
    : window.sessionStorage;
  const staleStorage = persistent ? window.sessionStorage : window.localStorage;

  targetStorage.setItem(TOKEN_STORAGE_KEY, state.token);
  targetStorage.setItem(REMEMBER_SESSION_STORAGE_KEY, persistent ? "1" : "0");
  staleStorage.removeItem(TOKEN_STORAGE_KEY);
  staleStorage.removeItem(USER_STORAGE_KEY);
  staleStorage.removeItem(REMEMBER_SESSION_STORAGE_KEY);
  persistUser();
}

function persistUser() {
  getSessionStorage().setItem(USER_STORAGE_KEY, JSON.stringify(state.user));
}

